import {createClient} from '@supabase/supabase-js';
import {emptyState, diff, hydrate, flatten, validateImport} from './sync-core.js';
const api=window.Casa;
const configured=Boolean(__SUPABASE_URL__ && __SUPABASE_KEY__);
const bar=document.createElement('div');bar.className='sync-bar';bar.setAttribute('role','status');
document.querySelector('.topbar').after(bar);
let client,user,house,channel,versions=new Map(),baseline,ready=false,busy=false,pending=null,refreshNeeded=false,recovery=false,connectionReady=false,refreshSequence=0,flushing=false;
const localBackup=api.snapshot();
const preferences=()=>api.snapshot().settings||{};
const status=(message,action)=>{bar.replaceChildren();const text=document.createElement('span');text.textContent=message;bar.append(text);if(action){const button=document.createElement('button');button.className='text-button';button.textContent=action.label;button.onclick=action.run;bar.append(button)}};
const lock=()=>{document.querySelector('main').inert=Boolean(configured&&(!ready||busy||!navigator.onLine));const form=document.querySelector('#dialog form');if(form&&!form.closest('[data-account]'))form.inert=busy;};
const cacheKey=()=>`casa-cloud:${user.id}:${house}`;
const pendingKey=()=>`${cacheKey()}:pending`;
function setState(value){api.replace(value);baseline=structuredClone(value);lock();}
function accountError(error){const message=error?.message||'';if(/revision_conflict/.test(message))return 'Este registro mudou no outro aparelho. Sua alteração não substituiu a versão compartilhada.';if(/invalid_invite/.test(message))return 'O convite é inválido, expirou ou já foi usado.';if(/household_full/.test(message))return 'Este espaço já tem dois membros.';if(/house_not_empty/.test(message))return 'Este espaço já possui registros. A importação foi cancelada.';if(/already_member|duplicate key/.test(message))return 'A conta já pertence a um espaço ou o nome já está em uso.';if(/Invalid login credentials/.test(message))return 'E-mail ou senha incorretos.';if(/Email not confirmed/.test(message))return 'Confirme seu e-mail antes de entrar.';return 'Não foi possível concluir. Verifique sua conexão e tente novamente.';}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function accountModal(title,html){api.modal(title,html);document.querySelector('#dialog').dataset.account='true';document.querySelector('#dialog').addEventListener('close',()=>{delete document.querySelector('#dialog').dataset.account},{once:true});}
function login(){accountModal('Entrar no Casa',`<form id="cloud-login" class="form-fields"><label>E-mail<input name="email" type="email" autocomplete="username" required></label><label>Senha<input name="password" type="password" autocomplete="current-password" minlength="8" required></label><p class="helper">Cada pessoa usa sua própria conta.</p><p id="account-error" class="form-error" role="alert"></p><div class="form-actions"><button type="button" id="cloud-signup">Criar conta</button><button class="primary">Entrar</button></div><button type="button" id="cloud-reset" class="text-button">Esqueci minha senha</button></form>`);
 const form=document.querySelector('#cloud-login');
 async function submit(mode){if(!form.reportValidity())return;const f=new FormData(form);form.inert=true;const credentials={email:f.get('email').trim(),password:f.get('password')};const result=mode==='signup'?await client.auth.signUp({...credentials,options:{emailRedirectTo:location.origin+location.pathname}}):await client.auth.signInWithPassword(credentials);form.inert=false;if(result.error){document.querySelector('#account-error').textContent=accountError(result.error);return}if(!result.data.session){document.querySelector('#account-error').textContent='Confirme o cadastro no e-mail e entre na sua conta.';return}document.querySelector('#dialog').close();await connect(result.data.session.user);}
 form.onsubmit=e=>{e.preventDefault();submit('login')};document.querySelector('#cloud-signup').onclick=()=>submit('signup');document.querySelector('#cloud-reset').onclick=async()=>{const input=form.elements.email;if(!input.reportValidity())return;const result=await client.auth.resetPasswordForEmail(input.value.trim(),{redirectTo:location.origin+location.pathname});document.querySelector('#account-error').textContent=result.error?accountError(result.error):'Se a conta existir, você receberá um link de recuperação.'};
}
function resetPassword(){recovery=true;accountModal('Nova senha',`<form id="cloud-password" class="form-fields"><label>Nova senha<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><p role="alert" id="account-error"></p><button class="primary">Salvar senha</button></form>`);document.querySelector('#cloud-password').onsubmit=async e=>{e.preventDefault();const result=await client.auth.updateUser({password:new FormData(e.target).get('password')});if(result.error){document.querySelector('#account-error').textContent=accountError(result.error);return}recovery=false;document.querySelector('#dialog').close();await connect(result.data.user)};}
function onboarding(){accountModal('Espaço da família',`<form id="cloud-house" class="form-fields"><label>Seu nome<input name="name" required maxlength="60" autocomplete="given-name"></label><label>Nome do espaço<input name="house" value="Casa" maxlength="80"></label><label>Código de convite (se recebeu um)<input name="invite" autocomplete="off" placeholder="Cole o código aqui"></label><p id="account-error" class="form-error" role="alert"></p><div class="form-actions"><button class="primary">Continuar</button></div></form>`);document.querySelector('#cloud-house').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),code=f.get('invite').trim(),result=await client.rpc(code?'join_household':'create_household',code?{invite_token:code,member_name:f.get('name').trim()}:{house_name:f.get('house').trim(),member_name:f.get('name').trim()});if(result.error){document.querySelector('#account-error').textContent=accountError(result.error);return}document.querySelector('#dialog').close();await connect(user)};}
async function invite(){const {data,error}=await client.rpc('create_household_invite');if(error){api.toast(accountError(error));return}accountModal('Convidar para o Casa',`<p>O código vale por 24 horas e permite uma entrada. Compartilhe com sua esposa ou seu marido.</p><label class="form-fields">Código<input readonly value="${data}" aria-label="Código do convite"></label><p>A outra pessoa cria a própria conta e informa este código em Espaço da família.</p>`);}
async function readRows(){let rows=[],offset=0;while(true){const result=await client.from('household_records').select('*').eq('household_id',house).order('kind').order('item_id').range(offset,offset+999);if(result.error)throw result.error;rows.push(...result.data);if(result.data.length<1000)return rows;offset+=1000;}}
async function refresh(force=false){if(!house||busy||pending)return;if(document.querySelector('#dialog').open&&!force){refreshNeeded=true;return}const sequence=++refreshSequence,activeHouse=house;try{const rows=await readRows();if(sequence!==refreshSequence||activeHouse!==house||busy||pending)return;if(!force&&document.querySelector('#dialog').open){refreshNeeded=true;return}const data=hydrate(rows,preferences());versions=data.versions;localStorage.setItem(cacheKey(),JSON.stringify(rows));setState(data.state);ready=true;refreshNeeded=false;lock();status(connectionReady?'Sincronizado':'Conectando atualização ao vivo…')}catch{status('Sem conexão com os dados. Tentar novamente.',{label:'Tentar',run:()=>refresh()});}}
async function connect(account){if(busy)return;user=account;ready=false;connectionReady=false;lock();status('Carregando seu espaço…');if(channel)await client.removeChannel(channel);
 const {data:member,error}=await client.from('household_members').select('*').eq('user_id',user.id).maybeSingle();if(error){status(accountError(error),{label:'Tentar',run:()=>connect(user)});return}if(!member){status('Crie seu espaço ou aceite um convite.',{label:'Configurar',run:onboarding});onboarding();return}house=member.household_id;
 const members=await client.from('household_members').select('*').eq('household_id',house);if(members.error){status(accountError(members.error));return}api.setMembers(members.data.map(m=>m.display_name));api.setViewer(member.display_name);
 try {pending=JSON.parse(localStorage.getItem(pendingKey())||'null');const cached=JSON.parse(localStorage.getItem(cacheKey())||'null');if(cached){const data=hydrate(cached,preferences());versions=data.versions;setState(data.state);}}catch{pending=null;status('Não foi possível ler o cache local.');}
 channel=client.channel(`house:${house}`).on('postgres_changes',{event:'*',schema:'public',table:'household_records',filter:`household_id=eq.${house}`},()=>{refreshNeeded=true;refresh()}).subscribe(value=>{connectionReady=value==='SUBSCRIBED';if(connectionReady){if(pending)flush();else refresh()}else if(value==='CHANNEL_ERROR'||value==='TIMED_OUT'){status('Atualização ao vivo indisponível. Reconexão automática.');}});
 if(pending){busy=true;await flush()}else await refresh(true);
}
function queuedSave(importing=false){if(!house||!ready){api.toast('Entre e aguarde a sincronização antes de editar.');return}if(busy||pending)return;if(!navigator.onLine){setState(baseline);api.toast('Sem conexão. Edições ficam disponíveis quando a conexão voltar.');return}
 const next=api.snapshot(),changes=diff(baseline,next,versions);localStorage.setItem('casa-preferences',JSON.stringify(next.settings||{}));if(!changes.length){baseline=structuredClone(next);return}pending={operation:crypto.randomUUID(),changes,importing};try{localStorage.setItem(pendingKey(),JSON.stringify(pending))}catch{pending=null;setState(baseline);api.toast('Sem espaço para salvar com segurança. Exporte seus dados.');return}busy=true;lock();status('Salvando…');flush();
}
async function flush(){if(!pending||!house||flushing)return;flushing=true;busy=true;lock();const result=await client.rpc(pending.importing?'import_household_changes':'apply_household_changes',{house,operation:pending.operation,changes:pending.changes});flushing=false;if(result.error){if(/revision_conflict|access_denied|invalid_batch|invalid_record|operation_mismatch|house_not_empty/.test(result.error.message)){status(accountError(result.error),{label:'Revisar',run:reviewConflict});}else status('Alteração pendente. Será reenviada ao reconectar.',{label:'Tentar agora',run:flush});return}
 pending=null;localStorage.removeItem(pendingKey());busy=false;await refresh(true);lock();api.toast('Salvo para a família.');
}
function reviewConflict(){accountModal('Alteração não aplicada',`<p>${pending?.importing?'Este espaço já possui registros. A importação foi cancelada.':'Outro aparelho alterou um dos registros.'} Exporte sua tentativa antes de carregar a versão compartilhada.</p><div class="form-actions"><button id="export-attempt">Exportar tentativa</button><button id="discard-attempt" class="primary">Carregar versão compartilhada</button></div>`);document.querySelector('#export-attempt').onclick=()=>download(pending,'casa-alteracao-pendente.json');document.querySelector('#discard-attempt').onclick=async()=>{pending=null;localStorage.removeItem(pendingKey());busy=false;document.querySelector('#dialog').close();await refresh(true)};}
function importData(){accountModal('Importar dados',`<p>A importação só está disponível em um espaço vazio. Os dados locais originais permanecem neste navegador.</p><input type="file" id="import-file" accept="application/json,.json" aria-label="Arquivo de exportação"><p id="import-summary" role="status"></p><div class="form-actions"><button id="import-local">Usar dados deste navegador</button><button id="confirm-import" class="primary" disabled>Importar para a família</button></div>`);let candidate=null;const inspect=value=>{candidate=validateImport(value);document.querySelector('#import-summary').textContent=`${flatten(candidate).size} registros. Confira o arquivo antes de confirmar.`;document.querySelector('#confirm-import').disabled=false;};document.querySelector('#import-local').onclick=()=>{try{inspect({format:'casa-prototype-v1',state:localBackup})}catch(e){document.querySelector('#import-summary').textContent=e.message}};document.querySelector('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>2_000_000)throw new Error('Arquivo inválido ou maior que 2 MB.');inspect(JSON.parse(await file.text()))}catch(err){candidate=null;document.querySelector('#confirm-import').disabled=true;document.querySelector('#import-summary').textContent=err.message}};document.querySelector('#confirm-import').onclick=async()=>{if(!candidate)return;const rows=await readRows();if(rows.length){document.querySelector('#import-summary').textContent='Este espaço já possui registros. A importação foi cancelada.';return}api.replace({...candidate,settings:preferences()});document.querySelector('#dialog').close();queuedSave(true)};}
async function signOut(){if(pending){api.toast('Resolva a alteração pendente antes de sair.');return}await client.auth.signOut();if(channel)await client.removeChannel(channel);ready=false;house=null;user=null;setState(emptyState(preferences()));status('Entre para acessar os dados da família.',{label:'Entrar',run:login});lock();}
api.configure({enabled:configured,save:queuedSave,afterRender:lock,settings:container=>{const section=document.createElement('section');section.className='account-settings';const label=document.createElement('p');label.className='helper';label.textContent=!configured?'Conta compartilhada ainda não configurada.':user?`Conta: ${user.email}`:'Entre para acessar seu espaço.';section.append(label);const actions=!configured?[]:!user?[['Entrar',login]]:!house?[['Configurar espaço',onboarding],['Sair',signOut]]:[['Convidar pessoa',invite],['Importar dados',importData],['Sair',signOut]];for(const [name,run]of actions){const b=document.createElement('button');b.type='button';b.className='text-button';b.textContent=name;b.onclick=run;section.append(b)}container.append(section)}});
document.querySelector('#dialog').addEventListener('close',()=>{if(refreshNeeded&&!busy)refresh()});
window.addEventListener('offline',()=>{lock();status('Sem conexão · consulta aos dados já carregados')});window.addEventListener('online',()=>{lock();if(pending)flush();else if(user&&!house)connect(user);else refresh()});
if(!configured){status('Dados neste aparelho · conta compartilhada ainda não configurada');}
else {
 client=createClient(__SUPABASE_URL__,__SUPABASE_KEY__);
 api.replace(emptyState(JSON.parse(localStorage.getItem('casa-preferences')||'{}')));lock();
 client.auth.onAuthStateChange(event=>{if(event==='PASSWORD_RECOVERY')setTimeout(resetPassword,0);if(event==='SIGNED_OUT'&&user){ready=false;user=null;house=null;api.replace(emptyState(preferences()));lock();status('Sessão encerrada.',{label:'Entrar',run:login})}});
 client.auth.getSession().then(({data,error})=>{if(recovery)return;if(error){status('Não foi possível recuperar a sessão.',{label:'Entrar',run:login});return}if(data.session)connect(data.session.user);else status('Entre para acessar os dados da família.',{label:'Entrar',run:login})});
 setInterval(()=>{if(user&&house&&!busy&&navigator.onLine)refresh()},30000);
}